package com.godjiismp.weapons;
import com.google.gson.*;import net.fabricmc.loader.api.FabricLoader;import java.nio.file.*;
public final class WeaponsConfig {private WeaponsConfig(){} public static final String[] IDS={"skeleton_king_blade","stormcaller_spear","earthbreaker_hammer","crimson_moon_scythe","frostbite_bow","emberfang_axe"};public static double[] damage={9,8,10,9,8,9},speed={1.6,1.4,1.0,1.5,1.6,1.0},pvpMultiplier={.5,.5,.5,.5,.5,.5};public static int[] durability={1800,1500,2200,1600,1200,1800},requiredAttack={5,7,9,0,0,0},cooldownSeconds={12,6,15,0,0,0};public static double[] abilityDamage={8,6,6,0,0,0},radius={8,6,5,0,0,0},specialVsUndead={1.5,1,1,1,1,1};public static int[] chainTargets={1,2,0,0,0,0};public static int comboHits=3,comboWindowSeconds=4;public static double waveHalfWidth=.8,hammerPushHorizontal=.8,hammerPushVertical=.45;public static void load(){Path p=FabricLoader.getInstance().getConfigDir().resolve("godjiismp_weapons.json");try{JsonObject o=defaults();if(Files.exists(p)){JsonObject in=JsonParser.parseString(Files.readString(p)).getAsJsonObject();in.entrySet().forEach(e->o.add(e.getKey(),e.getValue()));}else Files.createDirectories(p.getParent());damage=arr(o,"damage",damage);speed=arr(o,"attackSpeed",speed);durability=intarr(o,"durability",durability);requiredAttack=intarr(o,"requiredAttackLevel",requiredAttack);cooldownSeconds=intarr(o,"cooldownSeconds",cooldownSeconds);abilityDamage=arr(o,"abilityDamage",abilityDamage);radius=arr(o,"abilityRadius",radius);chainTargets=intarr(o,"chainTargets",chainTargets);comboHits=o.get("comboHits").getAsInt();comboWindowSeconds=o.get("comboWindowSeconds").getAsInt();waveHalfWidth=o.get("waveHalfWidth").getAsDouble();hammerPushHorizontal=o.get("hammerPushHorizontal").getAsDouble();hammerPushVertical=o.get("hammerPushVertical").getAsDouble();specialVsUndead=arr(o,"undeadDamageMultiplier",specialVsUndead);pvpMultiplier=arr(o,"pvpDamageMultiplier",pvpMultiplier);Files.writeString(p,new GsonBuilder().setPrettyPrinting().create().toJson(o)+"\n");}catch(Exception e){throw new IllegalStateException("Invalid godjiismp_weapons.json",e);}}private static JsonObject defaults(){JsonObject o=new JsonObject();o.add("damage",new Gson().toJsonTree(damage));o.add("attackSpeed",new Gson().toJsonTree(speed));o.add("durability",new Gson().toJsonTree(durability));o.add("requiredAttackLevel",new Gson().toJsonTree(requiredAttack));o.add("cooldownSeconds",new Gson().toJsonTree(cooldownSeconds));o.add("abilityDamage",new Gson().toJsonTree(abilityDamage));o.add("abilityRadius",new Gson().toJsonTree(radius));o.add("chainTargets",new Gson().toJsonTree(chainTargets));o.addProperty("comboHits",comboHits);o.addProperty("comboWindowSeconds",comboWindowSeconds);o.addProperty("waveHalfWidth",waveHalfWidth);o.addProperty("hammerPushHorizontal",hammerPushHorizontal);o.addProperty("hammerPushVertical",hammerPushVertical);o.add("undeadDamageMultiplier",new Gson().toJsonTree(specialVsUndead));o.add("pvpDamageMultiplier",new Gson().toJsonTree(pvpMultiplier));return o;}private static double[] arr(JsonObject o,String k,double[] d){double[] a=new Gson().fromJson(o.get(k),double[].class);if(a.length!=d.length)throw new IllegalArgumentException(k+" array length");return a;}private static int[] intarr(JsonObject o,String k,int[] d){int[] a=new Gson().fromJson(o.get(k),int[].class);if(a.length!=d.length)throw new IllegalArgumentException(k+" array length");return a;}}

